function [beta] = beta_angle(inc, ltan, epoch)
%BETA_ANGLE  The beta angle of a Sun-synchronous orbit of inclination inc and local time of the ascending
%   node ltan at an epoch: the node sits (ltan - 12 h) x 15 deg/h east of the mean Sun, and
%   beta = asin(sin(inc) cos(dec) sin(raan - ra) + cos(inc) sin(dec)).
%   inc: real[deg] (passed a plain number)
%   ltan: real[h] (passed in s)
%   epoch: real[yr] (passed in s)
%   returns beta: real[rad] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    beta = 0;
    [ra, dec] = asils.relations.orbit.sun_ra_dec(epoch);
    raan = (ra + ((ltan - 43200) * ((2 * pi) / 86400)));
    h__24 = asin((((sin(inc) * cos(dec)) * sin((raan - ra))) + (cos(inc) * sin(dec))));
    if ~isreal(h__24), h__24 = NaN; end
    beta = h__24;
end
